<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Suporte da empresa';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_tickets'.$q);$labels=['open'=>'Aberto','resolved'=>'Resolvido','closed'=>'Encerrado'];$priorities=['low'=>'Baixa','normal'=>'Normal','high'=>'Alta'];$hidden=function($action)use($esc,$company_tickets_csrf,$request_key,$ticket){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_tickets_csrf" value="'.$esc($company_tickets_csrf).'"><input type="hidden" name="request_key" value="'.$esc($request_key).'">';if($ticket)echo '<input type="hidden" name="ticket_id" value="'.(int)$ticket['id'].'"><input type="hidden" name="revision" value="'.(int)$ticket['revision'].'">';}; ?>
<section class="company-settings-card"><h1>Suporte da empresa</h1><p>Chamados e mensagens internos da equipe. O registro não envia e-mail nem publica conteúdo no portal.</p><?php if($error){ ?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><a href="<?= $esc($url()); ?>">Reabrir chamados</a><?php } ?>
<?php if($ticket){ ?><h2>#<?= (int)$ticket['id']; ?> — <?= $esc($ticket['subject']); ?></h2><p><?= $esc($labels[$ticket['status']].' · Prioridade '.$priorities[$ticket['priority']]); ?></p><div style="white-space:pre-wrap"><?= $esc($ticket['body']); ?></div><h3>Histórico de mensagens</h3><?php foreach($ticket['replies'] as $reply){ ?><article><p><?= nl2br($esc($reply['body'])); ?></p><small>Funcionário #<?= (int)$reply['actor_id']; ?> · <?= $esc($reply['created_at']); ?></small></article><?php } ?>
<?php if($can_edit&&$ticket['status']==='open'){ ?><?= form_open($url());$hidden('reply'); ?><label for="ticket-reply">Registrar mensagem interna</label><textarea id="ticket-reply" name="reply" class="form-control" maxlength="12000" rows="5" required></textarea><button type="submit">Registrar mensagem</button><?= form_close(); ?><?php } ?>
<?php if($can_edit){ ?><h3>Estado e responsável</h3><?= form_open($url());$hidden('change'); ?><label for="ticket-state">Estado</label><select id="ticket-state" name="status" class="form-control"><?php foreach($labels as $state=>$label){ ?><option value="<?= $esc($state); ?>" <?= $ticket['status']===$state?'selected':''; ?>><?= $esc($label); ?></option><?php } ?></select><label for="ticket-priority">Prioridade</label><select id="ticket-priority" name="priority" class="form-control"><?php foreach($priorities as $value=>$label){ ?><option value="<?= $esc($value); ?>" <?= $ticket['priority']===$value?'selected':''; ?>><?= $esc($label); ?></option><?php } ?></select><label for="ticket-assignee">Responsável autorizado</label><select id="ticket-assignee" name="assignee_id" class="form-control" required><?php foreach($staff_options as $person){ ?><option value="<?= (int)$person['staffid']; ?>" <?= (int)$ticket['assignee_id']===(int)$person['staffid']?'selected':''; ?>><?= $esc(trim($person['firstname'].' '.$person['lastname'])); ?></option><?php } ?></select><button type="submit">Salvar estado e responsável</button><?= form_close(); ?><?php } ?><?php } ?>
<h2>Lista de chamados</h2><form method="get" action="<?= $esc($url()); ?>"><label for="ticket-search">Buscar assunto ou mensagem inicial</label><input id="ticket-search" name="search" class="form-control" maxlength="191"><button type="submit">Buscar chamados</button></form><table class="table"><thead><tr><th>Chamado</th><th>Estado</th><th>Prioridade</th></tr></thead><tbody><?php foreach($directory['items'] as $row){ ?><tr><td><a href="<?= $esc($url('?ticket='.(int)$row['id'])); ?>"><?= $esc($row['subject']); ?></a></td><td><?= $esc($labels[$row['status']]); ?></td><td><?= $esc($priorities[$row['priority']]); ?></td></tr><?php } ?></tbody></table><?php if($directory['next']!==null){ ?><a href="<?= $esc($url('?after='.$directory['next'])); ?>">Próxima página</a><?php } ?>
<?php if($can_create){ ?><h2>Novo chamado</h2><form method="get" action="<?= $esc($url()); ?>"><label for="tickets-client-search">Buscar cliente por nome ou documento</label><input id="tickets-client-search" name="client_search" class="form-control" maxlength="191"><button type="submit">Buscar clientes</button></form><?= form_open($url());$hidden('create'); ?><label for="ticket-client">Cliente autorizado</label><select id="ticket-client" name="ticket[client_id]" class="form-control" required><option value="">Selecione</option><?php foreach($clients as $client){ ?><option value="<?= (int)$client['userid']; ?>"><?= $esc($client['company']); ?></option><?php } ?></select><label for="ticket-new-assignee">Responsável autorizado</label><select id="ticket-new-assignee" name="ticket[assignee_id]" class="form-control" required><?php foreach($staff_options as $person){ ?><option value="<?= (int)$person['staffid']; ?>" <?= (int)$actor===(int)$person['staffid']?'selected':''; ?>><?= $esc(trim($person['firstname'].' '.$person['lastname'])); ?></option><?php } ?></select><label for="ticket-subject">Assunto</label><input id="ticket-subject" name="ticket[subject]" class="form-control" maxlength="191" required><label for="ticket-body">Mensagem inicial</label><textarea id="ticket-body" name="ticket[body]" class="form-control" maxlength="12000" rows="6" required></textarea><label for="ticket-new-priority">Prioridade</label><select id="ticket-new-priority" name="ticket[priority]" class="form-control"><?php foreach($priorities as $v=>$label){ ?><option value="<?= $esc($v); ?>" <?= $v==='normal'?'selected':''; ?>><?= $esc($label); ?></option><?php } ?></select><button type="submit">Abrir chamado</button><?= form_close(); ?><?php } ?></section><?php require APPPATH.'views/admin/companies/layout_tail.php'; ?>
